    private static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
    private static ResourceLocation key(String path){return ResourceLocation.fromNamespaceAndPath("lawsjustice",path);}
    private static ServerPlayer player(){var mc=Minecraft.getInstance();check(mc.getSingleplayerServer()!=null&&mc.player!=null,"Actual integrated player is absent");var player=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());check(player!=null,"Actual integrated PlayerList has no host");return player;}
    private static void server(Runnable action){var server=Minecraft.getInstance().getSingleplayerServer();check(server!=null,"No real integrated server");server.execute(()->{try{action.run();}catch(Throwable failure){serverFailure=failure;}});}
    private static Object field(Object owner,String name){try{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Missing production GUI field "+name,failure);}}
    private static JsonObject state(){var screen=Minecraft.getInstance().screen;if(screen==null||!List.of("pt.lawsjustice.client.JusticeScreen","pt.lawsjustice.client.CourtScreen").contains(screen.getClass().getName()))return null;try{return (JsonObject)screen.getClass().getMethod("currentState").invoke(screen);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Production custody screen lacks its state reader",failure);}}
    private static String string(JsonObject o,String key){return o!=null&&o.has(key)&&!o.get(key).isJsonNull()?o.get(key).getAsString():"";}
    private static boolean ready(){var s=state();if(!opened||s==null||!s.has("open")||!s.get("open").getAsBoolean())return false;check(string(s,"error").isEmpty(),"Authoritative custody error: "+string(s,"error"));realS2c=true;return true;}
    private static void scroll(int direction){var screen=Minecraft.getInstance().screen;int x=(int)field(screen,"px"),top=(int)field(screen,"bodyTop"),bottom=(int)field(screen,"bodyBottom");screen.mouseScrolled(x+30,(top+bottom)/2.0,0,direction*1000);}
    private static boolean click(String key){var screen=Minecraft.getInstance().screen;if(screen==null)return false;String expected=Component.translatable(key).getString();for(var child:List.copyOf(screen.children()))if(child instanceof AbstractButton button&&button.active&&(button.getMessage().getString().equals(expected)||button.getMessage().getContents() instanceof TranslatableContents text&&text.getKey().equals(key))){for(int i=0;i<50&&!button.visible;i++){int top=(int)field(screen,"bodyTop"),bottom=(int)field(screen,"bodyBottom"),x=(int)field(screen,"px");screen.mouseScrolled(x+30,(top+bottom)/2.0,0,button.getY()<top?1:-1);}if(!button.visible)continue;button.onPress();return true;}return false;}
    @SuppressWarnings("unchecked") private static void input(String key,String value){var inputs=(Map<String,EditBox>)field(Minecraft.getInstance().screen,"inputs");check(inputs.containsKey(key),"Production input missing: "+key);inputs.get(key).setValue(value);}
    private static void selected(String fieldName,UUID value){try{var screen=Minecraft.getInstance().screen;Field f=screen.getClass().getDeclaredField(fieldName);f.setAccessible(true);if(f.getType()==UUID.class)f.set(screen,value);else f.set(screen,value.toString());screen.resize(Minecraft.getInstance(),screen.width,screen.height);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Cannot select production UUID "+fieldName,failure);}}
    private static void tab(String name){var screen=Minecraft.getInstance().screen;check(state()!=null,"Production custody menu is not open");try{Field f=screen.getClass().getDeclaredField("tab");f.setAccessible(true);@SuppressWarnings({"unchecked","rawtypes"})Object value=Enum.valueOf((Class)f.getType(),name);f.set(screen,value);Field scroll=screen.getClass().getDeclaredField("scroll");scroll.setAccessible(true);scroll.setInt(screen,0);screen.resize(Minecraft.getInstance(),screen.width,screen.height);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Cannot exercise production custody tab "+name,failure);}}
    /** Invoked after a real native button. The following step verifies the corresponding authoritative mutation. */
    private static void request(String expected){var snapshot=state();check(snapshot!=null,"Native operation closed the menu unexpectedly");check(snapshot.has("nonce")&&snapshot.has("version"),"Authoritative mutation view lacks nonce/version");UUID.fromString(snapshot.get("nonce").getAsString());var row=new LinkedHashMap<String,Object>();row.put("operation",expected);row.put("observed_before_nonce",snapshot.get("nonce").getAsString());row.put("observed_before_version",snapshot.get("version").getAsLong());row.put("native_button_pressed_at",System.currentTimeMillis());REQUESTS.add(row);c2sCount++;}
    private static void courtInput(String key,String value){var screen=Minecraft.getInstance().screen;@SuppressWarnings("unchecked")var fields=(Map<String,?>)field(screen,"multiline");if(fields.containsKey(key)){try{fields.get(key).getClass().getMethod("setValue",String.class).invoke(fields.get(key),value);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Missing native court text input "+key,failure);}}else input(key,value);}
    private static void councilPresident(UUID ruler){try{Class<?> type=Class.forName("pt.realmcouncil.CouncilData");Object data=type.getMethod("get",net.minecraft.server.MinecraftServer.class).invoke(null,player().getServer());Object state=type.getField("state").get(data);Class<?> mandateType=Class.forName("pt.realmcouncil.domain.CouncilState$Mandate");Object mandate=mandateType.getConstructor().newInstance();long now=System.currentTimeMillis();mandateType.getField("electionId").set(mandate,UUID.fromString("6cb60513-a36f-4cb3-966c-1296cd2c7918"));mandateType.getField("playerId").set(mandate,ruler);mandateType.getField("name").set(mandate,ruler.equals(owner)?"Aveline Vale":"The next sworn president");mandateType.getField("title").set(mandate,"Demonstration elected presidency");mandateType.getField("beginsAt").setLong(mandate,now-10_000);mandateType.getField("endsAt").setLong(mandate,now+86_400_000);mandateType.getField("claimedAt").setLong(mandate,now-5_000);state.getClass().getField("mandate").set(state,mandate);((net.minecraft.world.level.saveddata.SavedData)data).setDirty();}catch(ReflectiveOperationException failure){throw new IllegalStateException("Actual sworn Realm Council president fixture failed",failure);}}
    private static void prepareCourt(){courtPrepared=false;server(()->{var p=player();place(COURT_DESK,"justice_desk");op(p,false);councilPresident(owner);check(!p.hasPermissions(2),"Court presidency fixture still has administrator powers");courtPrepared=true;});}
    private static void openCourt(){opened=false;server(()->{var p=player();p.connection.teleport(COURT_DESK.getX()+.5,161,COURT_DESK.getZ()-2,0,12);CourtService.open(p,COURT_DESK);opened=true;});}
    private static boolean courtReady(){return ready()&&"court".equals(string(state(),"kind"));}
    private static JsonObject courtCase(){var snapshot=state();if(snapshot==null||!snapshot.has("cases"))return null;for(var row:snapshot.getAsJsonArray("cases"))if(row.isJsonObject()&&caseId.toString().equals(string(row.getAsJsonObject(),"id")))return row.getAsJsonObject();return null;}
    private static void validateCourtModels(){var mc=Minecraft.getInstance();var block=BuiltInRegistries.BLOCK.get(key("justice_desk"));check(block!=Blocks.AIR,"Missing actual Mesa de Justiça");for(var state:block.getStateDefinition().getPossibleStates()){var model=mc.getBlockRenderer().getBlockModel(state);var quads=new ArrayList<BakedQuad>();quads.addAll(model.getQuads(state,null,RandomSource.create(0)));for(var face:Direction.values())quads.addAll(model.getQuads(state,face,RandomSource.create(0)));check(!quads.isEmpty(),"Justice desk has no actual baked geometry");for(var quad:quads)check(!quad.getSprite().contents().name().equals(MissingTextureAtlasSprite.getLocation()),"Missing actual justice-desk texture");MODEL_QUADS.put(state.toString(),quads.size());}for(String name:List.of("justice_desk","handcuffs","warrant")){var item=BuiltInRegistries.ITEM.get(key(name));check(item!=Items.AIR,"Missing actual court item "+name);var model=mc.getItemRenderer().getModel(new ItemStack(item),null,null,0);check(!model.getParticleIcon().contents().name().equals(MissingTextureAtlasSprite.getLocation()),"Missing court item texture "+name);}courtModels=true;CHECKS.add("All four real justice-desk facings and actual desk, handcuffs and warrant item models resolve original geometry and textures.");}
    private static void validateCourtCapture(String name){
        var screen=Minecraft.getInstance().screen;
        if(name.equals("laws-justice-court-desk.png")){check(screen==null,"The physical desk photograph was replaced by an old menu");return;}
        String expected=switch(name){case "laws-justice-court-cases.png","laws-justice-court-former-president.png"->"CASES";case "laws-justice-court-evidence.png"->"EVIDENCE";case "laws-justice-court-judgment.png"->"JUDGMENT";case "laws-justice-court-warrants.png"->"WARRANTS";default->"";};
        if(!expected.isEmpty())check(screen!=null&&screen.getClass().getSimpleName().equals("CourtScreen")&&field(screen,"tab").toString().equals(expected),"Court screenshot does not show its real native tab: "+name);
    }
    private static void compactCourt(){var mc=Minecraft.getInstance();var screen=mc.screen;for(String name:List.of("CASES","EVIDENCE","JUDGMENT","WARRANTS")){tab(name);screen.resize(mc,320,240);bounds(screen,320,240);for(int n=0;n<18;n++){int x=(int)field(screen,"px"),top=(int)field(screen,"bodyTop"),bottom=(int)field(screen,"bodyBottom");screen.mouseScrolled(x+20,(top+bottom)/2.0,0,-1);bounds(screen,320,240);}scroll(1);}screen.resize(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());CHECKS.add("All four native court tabs fit 320x240 with scrolling, using genuine server snapshots.");}
    private static void holdIssuedWarrant(){warrantHeld=false;server(()->{var p=player();var item=BuiltInRegistries.ITEM.get(key("warrant"));var inventory=p.getInventory();int found=-1;for(int i=0;i<inventory.getContainerSize();i++)if(inventory.getItem(i).is(item)){found=i;break;}check(found>=0,"The real issuing operation did not deliver its physical warrant");int selected=inventory.selected;ItemStack old=inventory.getItem(selected),warrant=inventory.getItem(found);inventory.setItem(found,old);inventory.setItem(selected,warrant);inventory.setChanged();p.containerMenu.broadcastChanges();warrantHeld=true;});}
    private static void quiet(){
        if(ModList.get().isLoaded("cronicasrp"))try{var type=Class.forName("pt.cronicasrp.client.ClientState");var pending=type.getDeclaredField("pending");pending.setAccessible(true);pending.setInt(null,0);var reset=Class.forName("pt.cronicasrp.client.OriginsCreationFlow").getDeclaredMethod("reset");reset.setAccessible(true);reset.invoke(null);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Companion character creation fixture failed",failure);}
        try{var mc=Minecraft.getInstance();Object tutorial=mc.getClass().getMethod("getTutorial").invoke(mc);@SuppressWarnings({"rawtypes","unchecked"})Object none=Enum.valueOf((Class)Class.forName("net.minecraft.client.tutorial.TutorialSteps"),"NONE");tutorial.getClass().getMethod("setStep",none.getClass()).invoke(tutorial,none);}catch(ReflectiveOperationException ignored){}
        try{Object toasts=Minecraft.getInstance().getToasts();toasts.getClass().getMethod("clear").invoke(toasts);}catch(ReflectiveOperationException ignored){}
    }
    private static void profile(ServerPlayer player){if(!ModList.get().isLoaded("cronicasrp"))return;try{Class<?> type=Class.forName("pt.cronicasrp.domain.CharacterProfile");Object profile=type.getConstructor(boolean.class,String.class,int.class,String.class,String.class,String.class,String.class,long.class,long.class,String.class).newInstance(true,"Aveline Vale",28,"origins:human","Custody demonstration character; no real disciplinary record.","Aveline Vale","Comum",0L,0L,"");Object attachment=((Supplier<?>)Class.forName("pt.cronicasrp.ModAttachments").getField("PROFILE").get(null)).get();Method setter=null;for(var method:player.getClass().getMethods())if(method.getName().equals("setData")&&method.getParameterCount()==2&&method.getParameterTypes()[0].isInstance(attachment)){setter=method;break;}check(setter!=null,"Missing Chronicles attachment setter");setter.invoke(player,attachment,profile);}catch(ReflectiveOperationException failure){throw new IllegalStateException("Actual optional RP profile fixture failed",failure);}}
    private static void op(ServerPlayer player,boolean value){var list=player.getServer().getPlayerList();if(value)list.getOps().add(new ServerOpListEntry(player.getGameProfile(),2,false));else list.getOps().remove(player.getGameProfile());list.setAllowCommandsForAllPlayers(false);check(player.hasPermissions(2)==value,"Actual vanilla operator permission did not change");}
    private static void place(BlockPos pos,String name){var level=player().serverLevel();var block=BuiltInRegistries.BLOCK.get(key(name));check(block!=Blocks.AIR,"Missing real justice block "+name);var state=block.defaultBlockState();if(state.hasProperty(BlockStateProperties.HORIZONTAL_FACING))state=state.setValue(BlockStateProperties.HORIZONTAL_FACING,Direction.NORTH);if(state.hasProperty(BlockStateProperties.DOUBLE_BLOCK_HALF))state=state.setValue(BlockStateProperties.DOUBLE_BLOCK_HALF,DoubleBlockHalf.LOWER);int flags=Block.UPDATE_CLIENTS|Block.UPDATE_KNOWN_SHAPE;level.setBlock(pos,state,flags);if(state.hasProperty(BlockStateProperties.DOUBLE_BLOCK_HALF))level.setBlock(pos.above(),state.setValue(BlockStateProperties.DOUBLE_BLOCK_HALF,DoubleBlockHalf.UPPER),flags);level.updateNeighborsAt(pos,block);}
    private static void prepare(){server(()->{
        var player=player();var server=player.getServer();var level=player.serverLevel();owner=player.getUUID();initialServerIdentity=System.identityHashCode(server);worldPath=server.getWorldPath(LevelResource.ROOT).toAbsolutePath().normalize();worldName=worldPath.getFileName().toString();
        check(!server.getWorldData().isAllowCommands(),"QA world must start with cheats disabled to prove real permission removal");op(player,true);profile(player);level.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,server);level.getGameRules().getRule(GameRules.RULE_WEATHER_CYCLE).set(false,server);level.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,server);level.getGameRules().getRule(GameRules.RULE_DO_IMMEDIATE_RESPAWN).set(true,server);level.getGameRules().getRule(GameRules.RULE_KEEPINVENTORY).set(true,server);level.setDayTime(4_000);level.setWeatherParameters(0,60_000,false,false);
        for(int x=-14;x<=14;x++)for(int z=-12;z<=15;z++){level.setBlock(new BlockPos(x,160,z),(Math.floorMod(x+z,7)==0?Blocks.CRACKED_STONE_BRICKS:Math.abs(x)<7&&z>=0&&z<=11?Blocks.POLISHED_ANDESITE:Blocks.STONE_BRICKS).defaultBlockState(),2);for(int y=161;y<=169;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),2);}
        for(int x=-6;x<=6;x++)for(int z=0;z<=11;z++)if(Math.abs(x)==6||z==0||z==11)for(int y=161;y<=165;y++){boolean entry=z==0&&x==0&&y<=162;boolean window=z==0&&(x>=-4&&x<=-2||x>=2&&x<=4)&&y>=162&&y<=163;if(entry||window)continue;level.setBlock(new BlockPos(x,y,z),(y==165||Math.abs(x)==6&&(z%4==0)?Blocks.POLISHED_DEEPSLATE:Blocks.STONE_BRICKS).defaultBlockState(),2);}
        for(int x:new int[]{-4,-3,-2,2,3,4})for(int y=162;y<=163;y++)place(new BlockPos(x,y,0),"prison_bars");place(new BlockPos(0,161,0),"prison_door");place(new BlockPos(1,162,0),"reinforced_lock");place(CONTROL,"prison_control");place(INNER_CONTROL,"prison_control");
        for(int x=1;x<=4;x++)for(int z=5;z<=8;z++)if(x==1||x==4||z==5||z==8)for(int y=161;y<=163;y++){if(z==5&&x==2&&y<=162)continue;place(new BlockPos(x,y,z),"prison_bars");}place(new BlockPos(2,161,5),"prison_door");
        for(int x:new int[]{-5,5})for(int z:new int[]{-3,9}){level.setBlock(new BlockPos(x,161,z),Blocks.POLISHED_DEEPSLATE_WALL.defaultBlockState(),2);level.setBlock(new BlockPos(x,162,z),Blocks.LANTERN.defaultBlockState(),2);}
        level.setBlock(new BlockPos(-4,161,2),Blocks.BOOKSHELF.defaultBlockState(),2);level.setBlock(new BlockPos(-4,162,2),Blocks.LANTERN.defaultBlockState(),2);level.setBlock(new BlockPos(3,161,9),Blocks.CAULDRON.defaultBlockState(),2);
        var selector=BuiltInRegistries.ITEM.get(key("area_selector"));check(selector!=Items.AIR,"Missing original area selector item");var frame=new ItemFrame(level,new BlockPos(-5,162,-1),Direction.NORTH);frame.setItem(new ItemStack(selector));level.addFreshEntity(frame);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(selector));
        preparedAt=System.currentTimeMillis();prepared=true;
    });}
    private static void move(double x,double y,double z,float yaw,float pitch){cameraX=x;cameraY=y;cameraZ=z;cameraYaw=yaw;cameraPitch=pitch;moved=false;server(()->{var player=player();player.getAbilities().mayfly=true;player.getAbilities().flying=true;player.onUpdateAbilities();player.connection.teleport(x,y,z,yaw,pitch);moved=true;});}
    private static boolean cameraReady(){var mc=Minecraft.getInstance();if(!moved||mc.player==null||mc.level==null||mc.player.distanceToSqr(cameraX,cameraY,cameraZ)>.04)return false;mc.player.setYRot(cameraYaw);mc.player.yRotO=cameraYaw;mc.player.setXRot(cameraPitch);mc.player.xRotO=cameraPitch;mc.player.setYHeadRot(cameraYaw);mc.player.setYBodyRot(cameraYaw);mc.setCameraEntity(mc.player);return true;}
    private static void open(BlockPos pos){opened=false;server(()->{var p=player();if(JusticeData.get(p.getServer()).ledger().active().get(p.getUUID())==null)p.connection.teleport(pos.getX()+.5,161,pos.getZ()-2,0,10);JusticeService.open(p,pos);opened=true;});}
    private static void select(BlockPos a,BlockPos b,BlockPos anchor){selected=false;server(()->{var p=player();p.setPos(a.getX()+.5,a.getY()+1,a.getZ()+.5);JusticeService.select(p,a,false);p.setPos(b.getX()+.5,b.getY()+1,b.getZ()+.5);JusticeService.select(p,b,false);p.setPos(anchor.getX()+.5,anchor.getY()+1,anchor.getZ()+.5);JusticeService.select(p,anchor.below(),true);p.connection.teleport(CONTROL.getX()+.5,161,CONTROL.getZ()-2,0,10);JusticeService.handle(p,"refresh","{}");selected=true;});}
    private static void validateModels(){var mc=Minecraft.getInstance();for(String name:BLOCKS){var block=BuiltInRegistries.BLOCK.get(key(name));check(block!=Blocks.AIR,"Missing justice block "+name);for(var state:block.getStateDefinition().getPossibleStates()){var model=mc.getBlockRenderer().getBlockModel(state);var quads=new ArrayList<BakedQuad>();quads.addAll(model.getQuads(state,null,RandomSource.create(0)));for(Direction side:Direction.values())quads.addAll(model.getQuads(state,side,RandomSource.create(0)));check(!quads.isEmpty(),"Empty custom justice geometry: "+state);check(!model.getParticleIcon().contents().name().equals(MissingTextureAtlasSprite.getLocation()),"Missing justice particle: "+state);for(var quad:quads)check(!quad.getSprite().contents().name().equals(MissingTextureAtlasSprite.getLocation()),"Missing justice texture: "+state);MODEL_QUADS.put(state.toString(),quads.size());}}
        for(String name:new String[]{"prison_door","prison_bars","reinforced_lock","prison_control","area_selector"}){var item=BuiltInRegistries.ITEM.get(key(name));check(item!=Items.AIR,"Missing justice creative item "+name);var model=mc.getItemRenderer().getModel(new ItemStack(item),null,null,0);check(!model.getParticleIcon().contents().name().equals(MissingTextureAtlasSprite.getLocation()),"Missing justice item texture "+name);}CHECKS.add("All native door states and four facings of bars, lock and control have baked geometry with resolved textures; all five original item models resolve.");}
    private static void bounds(Screen screen,int width,int height){int count=0;for(var child:screen.children())if(child instanceof AbstractWidget widget&&widget.visible){count++;check(widget.getX()>=0&&widget.getY()>=0&&widget.getX()+widget.getWidth()<=width&&widget.getY()+widget.getHeight()<=height,"Visible custody control exceeds "+width+"x"+height+": "+widget.getMessage().getString());}check(count>0,"No native custody controls were checked");}
    private static void compact(boolean admin){var mc=Minecraft.getInstance();var screen=mc.screen;for(String name:admin?List.of("OVERVIEW","PRISONS","CELLS","SENTENCES","HISTORY"):List.of("OVERVIEW")){tab(name);screen.resize(mc,320,240);bounds(screen,320,240);for(int n=0;n<20;n++){int x=(int)field(screen,"px"),top=(int)field(screen,"bodyTop"),bottom=(int)field(screen,"bodyBottom");screen.mouseScrolled(x+20,(top+bottom)/2.0,0,-1);bounds(screen,320,240);}scroll(1);}screen.resize(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());CHECKS.add((admin?"All five administrator tabs":"The read-only prisoner's status")+" fit 320x240; visible widget bounds remain valid while scrolling.");}
    private static void photo(long now){quiet();var mc=Minecraft.getInstance();if(mc.screen!=null){mc.screen.setFocused(null);for(var child:mc.screen.children())if(child instanceof AbstractWidget widget)widget.setFocused(false);}long window=mc.getWindow().getWindow();double away=5+CAPTURES.size()%3;GLFW.glfwSetCursorPos(window,away,5);try{var move=mc.mouseHandler.getClass().getDeclaredMethod("onMove",long.class,double.class,double.class);move.setAccessible(true);move.invoke(mc.mouseHandler,window,away,5.0);}catch(ReflectiveOperationException failure){throw new IllegalStateException("QA cursor callback could not move outside the gallery frame",failure);}nextAction=now+700;}
    private static void capture(String name)throws Exception{validateCourtCapture(name);Files.createDirectories(OUT);check(Minecraft.getInstance().options.guiScale().get()==2,"Gallery must use GUI scale 2");try(var image=Screenshot.takeScreenshot(Minecraft.getInstance().getMainRenderTarget())){check(image.getWidth()==1600&&image.getHeight()==900,"Actual framebuffer must be1600x900");image.writeToFile(OUT.resolve(name));}CAPTURES.add(name);System.out.println("JUSTICE_CLIENT_CAPTURE "+name);}
    private static void publishLan(){server(()->{try{var s=player().getServer();if(!s.isPublished()){int port;try(var socket=new ServerSocket(0)){port=socket.getLocalPort();}check(s.publishServer(GameType.CREATIVE,false,port),"Actual Open to LAN failed");}check(s.isPublished(),"Integrated world is not actually published to LAN");lanPublished=true;}catch(Exception failure){throw new IllegalStateException("LAN publishing failed",failure);}});}
